      'Собственная разработка — от библиотеки распознавания номеров до городских платформ данных. Нажмите на карточку, чтобы посмотреть состав продукта.': 'Собственная разработка — от библиотеки распознавания номеров до городских платформ данных. Нажмите на карточку, чтобы посмотреть состав продукта.',
      'Компания закрывает не одну задачу, а весь контур: фиксация нарушений, видеоаналитика, городские платформы, связь, взимание платы за проезд, мониторинг с БПЛА и локализация производства.': 'Компания закрывает не одну задачу, а весь контур: фиксация нарушений, видеоаналитика, городские платформы, связь, взимание платы за проезд, мониторинг с БПЛА и локализация производства.',
      'Оборудование выпускается на собственном производстве, поэтому вы покупаете напрямую, без посредников и лишних наценок. Каждый комплекс проходит контроль качества и поставляется с гарантией, полным комплектом документов и сертификатами соответствия.': 'Оборудование выпускается на собственном производстве, поэтому вы покупаете напрямую, без посредников и лишних наценок. Каждый комплекс проходит контроль качества и поставляется с гарантией, полным комплектом документов и сертификатами соответствия.',
      'Мы производим программно-аппаратные комплексы фиксации нарушений ПДД — от схемотехники и встроенного программного обеспечения до серийной сборки и выпускного контроля качества. Это собственная разработка, а не перепродажа чужого оборудования под своей маркой.': 'Мы производим программно-аппаратные комплексы фиксации нарушений ПДД — от схемотехники и встроенного программного обеспечения до серийной сборки и выпускного контроля качества. Это собственная разработка, а не перепродажа чужого оборудования под своей маркой.',
      'За более чем 15 лет работы наши комплексы были поставлены на городские дороги, магистрали и объекты транспортной инфраструктуры. Мы делаем ставку на надёжность, точность измерений и долгий срок службы оборудования в любых климатических условиях — от −50 °C до +70 °C.': 'За более чем 15 лет работы наши комплексы были поставлены на городские дороги, магистрали и объекты транспортной инфраструктуры. Мы делаем ставку на надёжность, точность измерений и долгий срок службы оборудования в любых климатических условиях — от −50 °C до +70 °C.',
      'OLAN HIGH TECH PROJECT — производитель и поставщик интеллектуальных комплексов автоматической фиксации нарушений правил дорожного движения. Мы выпускаем сертифицированное оборудование для контроля скорости, проезда на красный свет, нарушений правил парковки, проезда железнодорожных переездов и выезда на полосу общественного транспорта.': 'OLAN HIGH TECH PROJECT — производитель и поставщик интеллектуальных комплексов автоматической фиксации нарушений правил дорожного движения. Мы выпускаем сертифицированное оборудование для контроля скорости, проезда на красный свет, нарушений правил парковки, проезда железнодорожных переездов и выезда на полосу общественного транспорта.',
