      uk: 'TRC створено для перехресть, де важливо все одразу: сигнал світлофора, стоп-лінія, швидкість і траєкторія. Комплекс синхронізується з фазами світлофора, фіксує проїзд на червоне та виїзд за стоп-лінію, вимірює швидкість на відстані до 350 метрів і відстежує траєкторію кожного автомобіля. Камера 4K зберігає фото- та відеодокази, а журнал подій містить повну історію кожного порушення.',
