  mission: {
    ru: 'Мы стремимся к тому, чтобы города Узбекистана и всего региона управлялись данными, а не догадками: чтобы каждое нарушение фиксировалось неотвратимо, каждая дорога была под контролем, а технологии для этого создавались здесь, а не закупались за рубежом.',
    en: 'Our goal is for cities in Uzbekistan and across the region to be run on data rather than guesswork: every violation recorded without exception, every road under control, and the technology behind it built here rather than imported.',
    uz: 'Biz O\'zbekiston va butun mintaqa shaharlari taxminlar bilan emas, ma\'lumotlar asosida boshqarilishiga intilamiz: har bir qoidabuzarlik muqarrar qayd etilsin, har bir yo\'l nazoratda bo\'lsin, buning uchun texnologiyalar esa chetdan sotib olinmasdan shu yerda yaratilsin.',
    zh: '我们希望乌兹别克斯坦乃至整个地区的城市依靠数据而非猜测来治理：让每一起违法都必被记录，每一条道路都在管控之中，而支撑这一切的技术在本地创造，而不是从国外采购。',
    ar: 'نسعى إلى أن تُدار مدن أوزبكستان والمنطقة كلها بالبيانات لا بالتخمين: أن تُرصد كل مخالفة حتمًا، وأن يكون كل طريق تحت المراقبة، وأن تُصنع التقنية اللازمة لذلك هنا لا أن تُشترى من الخارج.',
    uk: 'Ми прагнемо, щоб міста Узбекистану й усього регіону керувалися даними, а не здогадками: щоб кожне порушення фіксувалося невідворотно, кожна дорога була під контролем, а технології для цього створювалися тут, а не закуповувалися за кордоном.',
  },
