          uk: 'Два літакові БпЛА з розмахом крила 2,94 м. Старша модель стартує з катапульти, тримається в повітрі до 3 годин і пролітає до 200 км із навантаженням до 2 кг — RGB-камерою Sony LR1 або середньоформатною Fujifilm GFX100RF; її перевозять автомобілем, обслуговують дві людини, до польоту вона готова за 20 хвилин. Полегшена модель запускається з рук, літає до 2,5 години й переноситься в рюкзаковому кейсі — з нею впорається один оператор, розгортання триває 15 хвилин.',
