      uk: 'Блокчейн-інфраструктура для випуску, забезпечення та обігу цифрових валют і токенів на базі Universa Blockchain — для держав, банків і корпорацій. Від цифрового золота та CBDC до розрахункових стейблкоїнів: смарт-контракти керують емісією та погашенням, оракули публікують підтвердження резервів безпосередньо в блокчейні, а емісія ніколи не перевищує підтверджений резерв. Вимоги регулятора — KYC, KYB, заморожування коштів — вбудовано в сам контракт, а мережа обробляє понад 25 000 транзакцій на секунду без майнінгу й майже без комісії.',
      zh: '基于Universa Blockchain的数字货币与代币发行、储备担保及流通的区块链基础设施，面向政府、银行和企业。从数字黄金、央行数字货币到结算型稳定币：智能合约管理发行与赎回，预言机将储备证明直接发布在链上，发行量始终不超过已确认的储备。KYC、KYB、资金冻结等监管要求内置于合约之中，网络每秒处理超过25,000笔交易，无需挖矿，手续费几乎为零。',
